// node build.mjs  (after `npm install` here): writes ../../assets/plugins/vega_runtime.js and scraper_runtime.js
import { build } from 'esbuild';
import fs from 'node:fs';

const bundle = async (entry, name, external = []) =>
  (await build({ entryPoints: [entry], bundle: true, write: false, format: 'iife', globalName: name, platform: 'browser', target: 'es2020', minify: true, external })).outputFiles[0].text;

const parts = [
  '// vega_runtime.js: generated by tool/vega_runtime/build.mjs (do not edit)\n',
  fs.readFileSync('polyfills.js', 'utf8'),
  'var __axiosLib = (function(){' + (await bundle('node_modules/axios/dist/browser/axios.cjs', '__a')) + '; return __a; })();\n',
  'var __cheerioLib = (function(){' + (await bundle('node_modules/cheerio/dist/browser/slim.js', '__c')) + '; return __c; })();\n',
  fs.readFileSync('adapter.js', 'utf8'),
];
fs.writeFileSync('../../assets/plugins/vega_runtime.js', parts.join('\n'));
console.log('vega_runtime.js', fs.statSync('../../assets/plugins/vega_runtime.js').size, 'bytes');

// The scraper-list runtime, loaded after vega_runtime.js for a scraper from a scraper list: the real
// crypto-js (its optional Node 'crypto' left out: it falls back to the engine's own), then the adapter.
const scraperParts = [
  '// scraper_runtime.js: generated by tool/vega_runtime/build.mjs (do not edit); runs after vega_runtime.js\n',
  'var __cryptoLib = (function(){' + (await bundle('node_modules/crypto-js/index.js', '__cj', ['crypto'])) + '; return __cj; })();\n',
  fs.readFileSync('scrapers.js', 'utf8'),
];
fs.writeFileSync('../../assets/plugins/scraper_runtime.js', scraperParts.join('\n'));
console.log('scraper_runtime.js', fs.statSync('../../assets/plugins/scraper_runtime.js').size, 'bytes');
